import os
from datetime import datetime, timedelta, timezone
from typing import Any, Dict, List, Optional

from google.cloud import monitoring_v3


def query_recent_datapoints(
    metric_name: str,
    minutes: int = 60,
    project_id: Optional[str] = None,
) -> List[Dict[str, Any]]:
    """
    Query recent datapoints for a named metric over a time window using Google Cloud Monitoring.

    Args:
        metric_name: Metric type name, e.g. "compute.googleapis.com/instance/cpu/utilization"
        minutes: Time window in minutes.
        project_id: Google Cloud project ID. If omitted, uses GOOGLE_CLOUD_PROJECT.

    Returns:
        A list of datapoint dictionaries sorted from newest to oldest.
    """
    project_id = project_id or os.environ.get("GOOGLE_CLOUD_PROJECT") or os.environ.get("GCLOUD_PROJECT")
    if not project_id:
        raise ValueError("project_id is required or GOOGLE_CLOUD_PROJECT/GCLOUD_PROJECT must be set")

    client = monitoring_v3.MetricServiceClient()
    project_name = f"projects/{project_id}"

    end_time = datetime.now(timezone.utc)
    start_time = end_time - timedelta(minutes=minutes)

    interval = monitoring_v3.TimeInterval(
        {
            "start_time": {"seconds": int(start_time.timestamp())},
            "end_time": {"seconds": int(end_time.timestamp())},
        }
    )

    metric_filter = f'metric.type = "{metric_name}"'

    results: List[Dict[str, Any]] = []
    for series in client.list_time_series(
        request={
            "name": project_name,
            "filter": metric_filter,
            "interval": interval,
            "view": monitoring_v3.ListTimeSeriesRequest.TimeSeriesView.FULL,
        }
    ):
        metric = dict(series.metric)
        resource = dict(series.resource)
        for point in series.points:
            value = point.value
            results.append(
                {
                    "metric": metric,
                    "resource": resource,
                    "point_time": point.interval.end_time.isoformat(),
                    "value": _extract_monitoring_value(value),
                }
            )

    results.sort(key=lambda item: item["point_time"], reverse=True)
    return results


def _extract_monitoring_value(value: monitoring_v3.TypedValue) -> Any:
    which = value.WhichOneof("value")
    if which == "double_value":
        return value.double_value
    if which == "int64_value":
        return value.int64_value
    if which == "string_value":
        return value.string_value
    if which == "bool_value":
        return value.bool_value
    if which == "distribution_value":
        return {
            "count": value.distribution_value.count,
            "mean": value.distribution_value.mean,
            "sum_of_squared_deviation": value.distribution_value.sum_of_squared_deviation,
        }
    if which == "money_value":
        return {
            "currency_code": value.money_value.currency_code,
            "units": value.money_value.units,
            "nanos": value.money_value.nanos,
        }
    if which == "value":
        return value.value
    return None
